export const clone=v=>structuredClone(v);
export const transforms=Array.from({length:8},(_,i)=>({quarterTurns:i%4,mirrorX:i>=4}));
export const schedule={segmentsPerPart:8,maxChordErrorM:.05,maxSegmentM:10,maxWork:2048};
export const line=(id,a,b)=>({kind:'line',id,a:clone(a),b:clone(b)});
export function region(id,w=2,d=2,{channel='surface',layerId='ground',material='border.paving',height=0,thickness=.1,policy='open',sides=['north','east','south','west']}={}){
  const vertices=[[0,0,height],[w,0,height],[w,d,height],[0,d,height]],outline={kind:'compound',id:id+'.outline',segments:vertices.map((a,i)=>line(id+'.segment.'+i,a,vertices[(i+1)%4]))};
  const r={kind:'nautilus-tile-recipe',version:1,id,contentVersion:1,features:['canonical-boundaries-v1'],frame:'local',shape:{kind:'region',id:id+'.region',outlines:[outline],baseM:height,thicknessM:thickness},reservations:[{id:'body',floorSlot:'base',channel,layerId,min:[0,0,height],max:[w,d,height+thickness]}],ports:[],allowedTransforms:clone(transforms),interior:{variantSeed:7,detail:1,skinId:'skin.original'},anchors:[{id:id+'.region',kind:'region',parentId:null}],templates:[]};
  const entries={north:{a:vertices[0],b:vertices[1],outward:[0,-1,0],tangent:[1,0,0],endpoint:[w/2,0,height],width:w},east:{a:vertices[1],b:vertices[2],outward:[1,0,0],tangent:[0,1,0],endpoint:[w,d/2,height],width:d},south:{a:vertices[3],b:vertices[2],outward:[0,1,0],tangent:[1,0,0],endpoint:[w/2,d,height],width:w},west:{a:vertices[0],b:vertices[3],outward:[-1,0,0],tangent:[0,1,0],endpoint:[0,d/2,height],width:d}};
  for(const side of sides){const v=entries[side];r.ports.push({id:side,faceId:side,floor:{slot:'base',offsetM:height},endpoint:v.endpoint,outward:v.outward,tangent:v.tangent,flow:{policy:'none',vector:null},widthM:v.width,thicknessM:thickness,channel,layerId,policy,profiles:{surface:{id:'surface.shared',version:1},edge:{id:'edge.flat',version:1},material:{id:material,version:1},border:{id:'border.flat',version:1}},boundary:{curve:line(id+'.boundary.'+side,v.a,v.b),sampling:clone(schedule),normal:{kind:'constant',vector:[0,0,1]},materialIntervals:[{from:0,to:1,material:{id:material,version:1}}]},uv:{policy:'world-linear-exact-v1',axes:[[1,0,0],[0,1,0]],scaleM:[1,1],phase:[0,0]}});}
  return r;
}
export function field(id,mask=15,variant=0){const r=region(id,1,1),s={kind:'field-cell',id:id+'.field',bounds:[0,0,1,1],values:Array.from({length:4},(_,i)=>mask&(1<<i)?1:-1),heights:[0,0,0,0],paint:[.5,.5,.5,.5],fieldAmplitude:.34,heightAmplitudeM:.08,variantSeed:variant,saddle:'connect-positive'};r.shape=s;for(const p of r.ports)p.boundary.normal={kind:'field-cell',field:clone(s)};return r;}
export const put=(T,id,recipe,origin=[0,0,0],options={})=>({id,recipeId:recipe.id,contentDigest:T.compileTileRecipe(recipe).contentDigest,origin,floorBindings:{base:'ground'},transform:{quarterTurns:0,mirrorX:false},locked:false,anchorIds:recipe.anchors.map(a=>a.id),...options});
export const join=(id,a,af,b,bf)=>({id,a:{instanceId:a,faceId:af,portIds:null},b:{instanceId:b,faceId:bf,portIds:null}});
export function setup(T,recipes,instances=[],joins=[],relations=[]){const catalogue=T.createTileCatalogue(recipes),layout={kind:'nautilus-tile-layout',version:1,id:'fixture-yard',revision:0,floors:[{id:'ground',elevationM:0},{id:'upper',elevationM:3}],catalogueDigest:catalogue.digest,instances,joins,relations,selection:{seed:7,policyVersion:1},extensions:{authoredIntent:{retained:true,controls:[.123456789,3.5000000001]}}};return {catalogue,layout,bundle:T.tileBundle(layout,catalogue)};}
export function repairRequest(T,bundle,options={}){const contextToken='a'.repeat(64);return {request:{version:1,id:'edit-1',expected:{revision:bundle.layout.revision,layoutDigest:T.tileLayoutToken(bundle.layout),catalogueDigest:bundle.layout.catalogueDigest,contextToken},selection:{seed:7,policyVersion:1},replaceIds:[],removeIds:[],slots:[],joins:clone(bundle.layout.joins),relations:clone(bundle.layout.relations),recipeUpdates:[],maxSteps:1000,maxClosure:128,maxSpatialTests:200000,maxGeometryWork:200000,neighbourRadiusM:0,...options},context:{contextToken}};}
export const slot=(id,recipeIds,origin=[0,0,0],options={})=>({id,origin,floorBindings:{base:'ground'},alternatives:recipeIds.map(recipeId=>({recipeId,transform:{quarterTurns:0,mirrorX:false}})),locked:false,anchorIds:[],...options});
